using System.Text;
using Hopkey.Core.Util;

namespace Hopkey.Core.Pinyin;

/// <summary>
/// U+4E00–U+9FFF → pinyin initial ('a'..'z', 0 = unknown) and toneless full pinyin readings (polyphones included,
/// most common first). Loaded from the embedded pinyin-data.txt (generated by tools/gen-pinyin.cs from
/// mozillazg/pinyin-data, MIT). Falls back to GB2312 level-1 boundaries (initials only) if the resource is missing.
/// (The Windows Chinese IME is no longer used: on Windows 11 IFELanguage.GetPhonetic returns E_NOTIMPL.)
/// </summary>
public static class PinyinInitialsTable
{
    public const char First = '一';
    public const char Last = '鿿';
    public const int Size = Last - First + 1; // 20992

    private static readonly byte[] s_initials = new byte[Size];
    private static string[]?[] s_readings = new string[Size][];
    private static HashSet<string> s_syllables = new(StringComparer.Ordinal);
    private static volatile bool s_ready;
    private static readonly object s_gate = new();

    public static bool IsReady => s_ready;
    public static bool HasFullPinyin { get; private set; }

    /// <summary>Version bumps whenever the table content changes (callers may rebuild derived data).</summary>
    public static int Version { get; private set; }

    public static event Action? Updated;

    // GB2312 level-1 boundaries (code values) for each initial letter.
    private static readonly (int Code, char Letter)[] s_bounds =
    {
        (0xB0A1, 'a'), (0xB0C5, 'b'), (0xB2C1, 'c'), (0xB4EE, 'd'), (0xB6EA, 'e'), (0xB7A2, 'f'), (0xB8C1, 'g'),
        (0xB9FE, 'h'), (0xBBF7, 'j'), (0xBFA6, 'k'), (0xC0AC, 'l'), (0xC2E8, 'm'), (0xC4C3, 'n'), (0xC5B6, 'o'),
        (0xC5BE, 'p'), (0xC6DA, 'q'), (0xC8BB, 'r'), (0xC8F6, 's'), (0xCBFA, 't'), (0xCDDA, 'w'), (0xCEF4, 'x'),
        (0xD1B9, 'y'), (0xD4D1, 'z'),
    };
    private const int Level1End = 0xD7F9;

    public static void Initialize()
    {
        lock (s_gate)
        {
            if (s_ready) return;
            var sw = System.Diagnostics.Stopwatch.StartNew();
            if (!TryLoadEmbedded()) BuildFromGb2312();
            s_ready = true;
            Version++;
            Logger.Info($"Pinyin table ready in {sw.ElapsedMilliseconds}ms (full pinyin: {HasFullPinyin})");
        }
        // The index may have built its pinyin arena before the table was ready.
        try { Updated?.Invoke(); } catch { }
    }

    public static byte GetInitial(char c) => c is >= First and <= Last ? s_initials[c - First] : (byte)0;

    /// <summary>Toneless readings of a CJK char (most common first), or null.</summary>
    public static string[]? GetReadings(char c) => c is >= First and <= Last ? s_readings[c - First] : null;

    /// <summary>Most common reading, or null.</summary>
    public static string? GetFull(char c) => GetReadings(c)?[0];

    /// <summary>All distinct syllables in the table (for query segmentation).</summary>
    public static IReadOnlySet<string> Syllables => s_syllables;

    private static Dictionary<string, string> s_arenaInitials = new(StringComparer.Ordinal);

    /// <summary>
    /// The initials (as stored by <see cref="GetInitial"/>, i.e. of each char's first reading) under which a char
    /// that can be read as <paramref name="syllable"/> may appear: "hang" → "hx" (杭 h, 行 x).
    /// </summary>
    public static string ArenaInitials(string syllable) => s_arenaInitials.TryGetValue(syllable, out var s) ? s : syllable[..1];

    private static bool TryLoadEmbedded()
    {
        try
        {
            using var stream = typeof(PinyinInitialsTable).Assembly.GetManifestResourceStream("Hopkey.Core.Pinyin.pinyin-data.txt");
            if (stream == null) { Logger.Warn("Embedded pinyin table missing"); return false; }
            using var reader = new StreamReader(stream, Encoding.UTF8);
            var readings = new string[Size][];
            var intern = new Dictionary<string, string>(StringComparer.Ordinal);
            string? line;
            int filled = 0;
            while ((line = reader.ReadLine()) != null)
            {
                if (line.Length < 3 || line[0] == '#' || line[1] != ' ') continue;
                char c = line[0];
                if (c is < First or > Last) continue;
                var parts = line[2..].Split(',', StringSplitOptions.RemoveEmptyEntries);
                var list = new List<string>(parts.Length + 1);
                foreach (var p in parts) AddReading(list, p, intern);
                // "lv" users also type "lu" (and vice versa the data already lists both where common).
                foreach (var p in parts) if (p.Contains('v')) AddReading(list, p.Replace('v', 'u'), intern);
                readings[c - First] = list.ToArray();
                s_initials[c - First] = (byte)list[0][0];
                filled++;
            }
            if (filled < 1000) return false;
            var arena = new Dictionary<string, SortedSet<char>>(StringComparer.Ordinal);
            for (int i = 0; i < Size; i++)
            {
                var rs = readings[i];
                if (rs == null) continue;
                char ini = (char)s_initials[i];
                foreach (var r in rs)
                {
                    if (!arena.TryGetValue(r, out var set)) arena[r] = set = new SortedSet<char>();
                    set.Add(ini);
                }
            }
            // Primary initial first, so the most likely needle is generated first.
            s_arenaInitials = arena.ToDictionary(kv => kv.Key,
                kv => kv.Key[0] + new string(kv.Value.Where(c => c != kv.Key[0]).ToArray()), StringComparer.Ordinal);
            s_readings = readings;
            s_syllables = new HashSet<string>(intern.Keys, StringComparer.Ordinal);
            HasFullPinyin = true;
            return true;
        }
        catch (Exception ex)
        {
            Logger.Warn("Failed to load embedded pinyin table", ex);
            return false;
        }
    }

    private static void AddReading(List<string> list, string r, Dictionary<string, string> intern)
    {
        if (!intern.TryGetValue(r, out var s)) intern[r] = s = r;
        if (!list.Contains(s)) list.Add(s);
    }

    private static void BuildFromGb2312()
    {
        Encoding gb;
        try
        {
            Encoding.RegisterProvider(CodePagesEncodingProvider.Instance);
            gb = Encoding.GetEncoding(936);
        }
        catch (Exception ex)
        {
            Logger.Warn("GB2312 encoding unavailable; pinyin initials disabled", ex);
            return;
        }
        Span<char> one = stackalloc char[1];
        Span<byte> bytes = stackalloc byte[4];
        for (int i = 0; i < Size; i++)
        {
            one[0] = (char)(First + i);
            int n = gb.GetBytes(one, bytes);
            if (n != 2) continue;
            int code = (bytes[0] << 8) | bytes[1];
            if (code < s_bounds[0].Code || code > Level1End) continue;
            byte letter = 0;
            for (int b = s_bounds.Length - 1; b >= 0; b--)
            {
                if (code >= s_bounds[b].Code) { letter = (byte)s_bounds[b].Letter; break; }
            }
            s_initials[i] = letter;
        }
    }
}
